import {mountGoldSizing} from './gold-sizing-ui.js';
import {METHODS,GOLD_RULE,deriveMethod} from './gold-methods.js';
import {drawGoldChart} from './gold-chart.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number.isFinite(n)?n.toLocaleString('zh-CN',{maximumFractionDigits:3}):'待核验';
const label=s=>({analysis:'分析完成',method:'手法已确认',review:'待最终拍板',approved:'已拍板'}[s]||s);
function intradayFields(direction){return `<section id="goldIntradayParams" class="form-section" hidden><h3>第五法 · 独立分时参数</h3><p class="muted">第四法仍按日K管理；此处按当日有效${direction==='long'?'低':'高'}点防守。分时算法不预设，日K不能证明已经穿线。</p><div class="form-grid three"><label class="field wide">已确认的分时均线算法<input name="intradayAlgorithm" required placeholder="填写算法、重置范围和口径；不默认分钟MA10"></label><label class="field">触发确认<select name="intradayConfirmation" required><option value="">请选择</option><option value="cross">按计划穿越确认</option><option value="second">需要二次确认</option></select></label><label class="field wide" id="goldSecondConfirmation" hidden>二次确认条件<input name="intradayConfirmationRule"></label><label class="field">所属交易日（夜盘按交易日）<input type="date" name="intradayTradingDay" required></label><label class="field">高低点取值截止（北京时间）<input type="datetime-local" name="intradayReferenceAt" required></label><label class="field">当日有效${direction==='long'?'低':'高'}点<input type="number" step="any" name="intradayPivot" required></label><label class="field">外侧初始止损价（由本人指定）<input type="number" step="any" name="intradayStop" required></label></div><label class="gold-check"><input type="checkbox" name="intradayEnvironment" required>已获主线许可并呈易涨难跌或易跌难涨；不在无方向反复穿线中试做</label><label class="gold-check"><input type="checkbox" name="intradayStructure" required>以上日内高低点属于所填交易日，且在所记截止时刻已经可知，没有盘后回填</label></section>`}
function readIntraday(form){return {algorithm:form.elements.intradayAlgorithm.value,confirmation:form.elements.intradayConfirmation.value,confirmationRule:form.elements.intradayConfirmationRule.value,tradingDay:form.elements.intradayTradingDay.value,referenceAt:form.elements.intradayReferenceAt.value,pivot:Number(form.elements.intradayPivot.value),stop:Number(form.elements.intradayStop.value),environmentConfirmed:form.elements.intradayEnvironment.checked,structureConfirmed:form.elements.intradayStructure.checked}}
export async function mountGold(node,{api,card,accounts,toast,onApproved}) {
 let analysisStep=null,methodStep=null,busy=false;
 const url=`/api/workbench/cards/${encodeURIComponent(card.id)}/gold`;
 const call=async(action,payload)=>api(`${url}/${action}`,{method:'POST',body:JSON.stringify(payload||{})});
 const alive=()=>node.isConnected;
 async function action(fn,button){if(busy)return;busy=true;if(button)button.disabled=true;try{await fn()}catch(e){if(alive()){node.querySelector('#goldStatus').textContent=e.message;toast(e.message,true)}}finally{busy=false;if(button?.isConnected)button.disabled=false}}
 node.innerHTML=`<header class="section-head"><div><h2>${esc(card.name)} · 入场方案</h2><p class="muted">${esc(card.contract)} · ${card.direction==='long'?'多头':'空头'} · ${GOLD_RULE}</p></div><button type="button" class="secondary" id="analyzeGold">分析五种手法</button></header><ol class="gold-steps"><li>分析推荐</li><li>确认手法</li><li>审定价格与账户</li><li>本人拍板</li></ol><p id="goldStatus" role="status"></p><div id="goldAnalysis"></div><div id="goldChoice"></div><div id="goldSizing"></div><div id="goldTerms"></div><div id="goldReview"></div><details class="form-section"><summary>历史分析与审定</summary><div id="goldHistory"></div></details>${card.plan?`<details class="form-section"><summary>原计划版本 ${card.plan.version} · ${esc(card.plan.status)}</summary><p>入场 ${money(card.plan.payload.entry)} · 止损 ${money(card.plan.payload.stop)} · ${money(card.plan.risk.lots)} 手</p><p>${esc(card.plan.payload.pairType)}</p><p>${esc(card.plan.payload.exitRule)}</p></details>`:''}`;
 const $=s=>node.querySelector(s);
 const sizing=mountGoldSizing($('#goldSizing'),{card,accounts,api,onChange:applySizingToTerms});
 function updateAccountPreviews(){const form=$('#goldTermsForm');if(!form)return;const entry=Number(form.elements[card.direction==='long'?'entryMax':'entryMin'].value),stop=Number(form.elements.stop.value),hint=$('#goldActiveTermsHint');if(hint)hint.textContent='本次止损 '+(stop>0?money(stop):'待填写')+' 到价失效；仅在本人审定的入场区间 '+form.elements.entryMin.value+' ～ '+form.elements.entryMax.value+' 内等待触发。当前未接入实时触发核验。';for(const tr of form.querySelectorAll('[data-account]')){const result=sizing.previewFor({accountId:tr.dataset.account,entry,stop,riskPercent:Number(tr.querySelector('[name=riskPercent]').value)});tr.querySelector('[data-gold-sizing-lots]').textContent=result.lots===null?'待填写':money(result.lots)+' 手';tr.querySelector('[data-gold-sizing-loss]').textContent=result.riskPerLot===null?'':'每手止损 '+money(result.riskPerLot)+' 元';tr.querySelector('[data-gold-account-equity]').textContent=money(result.baseEquity)+' 元';}}
 function applySizingToTerms(values){const form=$('#goldTermsForm');$('#goldReview').innerHTML='';if(!form)return;for(const key of ['entryMin','entryMax'])form.elements[key].value=values.entry??'';form.elements.stop.value=values.stop??'';const row=[...form.querySelectorAll('[data-account]')].find(tr=>tr.dataset.account===values.accountId);if(row)row.querySelector('[name=riskPercent]').value=values.riskPercent??'';form.dirty=true;updateAccountPreviews();}
 function syncSizingFromTerms(){const f=$('#goldTermsForm');if(!f)return;const current=sizing.values(),row=[...f.querySelectorAll('[data-account]')].find(tr=>tr.dataset.account===current.accountId);sizing.setPrices({entry:Number(f.elements[card.direction==='long'?'entryMax':'entryMin'].value)||null,stop:Number(f.elements.stop.value)||null,riskPercent:row?Number(row.querySelector('[name=riskPercent]').value):current.riskPercent,mainCycle:f.elements.mainCycle.value},{isManual:true,notify:false});updateAccountPreviews();}

 node.querySelector('.gold-steps').insertAdjacentHTML('afterend','<details class="form-section"><summary>当前环境资料 · 板块指数口径</summary><div id="goldEnvironment" class="muted">正在读取当前环境资料…</div></details>');
 async function showEnvironment(){try{const e=await api(`/api/workbench/cards/${encodeURIComponent(card.id)}/environment?cycle=day`);if(!alive())return;$('#goldEnvironment').innerHTML=`<p>资料日期 ${esc(e.dataDate||'未取得')}；以下是当前证据，历史方案保留原版本。</p>${Object.entries(e.layers||{}).map(([key,l])=>`<p><b>${esc(({market:'大盘',sector:'板块',month:'月线',week:'周线',day:'日线'})[key]||key)}</b> · ${esc(l.target||'品种自身')} · ${esc(({long:'多头',short:'空头',neutral:'中性',unknown:'待核验'})[l.direction]||'待核验')}<small>${esc(l.source||'来源未取得')}</small></p>`).join('')}`}catch(e){if(alive())$('#goldEnvironment').textContent='环境资料未取得：'+e.message}}
 void showEnvironment();
 async function history(){const list=await api(url);if(!alive())return [];$('#goldHistory').innerHTML=list.map(x=>`<p>${esc(new Date(x.createdAt).toLocaleString('zh-CN'))} · ${label(x.stage)} ${x.derived?esc(METHODS.find(m=>m.id===x.derived.method)?.name):''}${x.stage==='review'?` · ${x.rows.length}个账户`:''}</p>`).join('')||'<p class="muted">暂无记录</p>';return list}
 function drawChart(a,start,end){
  drawGoldChart($('#goldChart'),a,{start,end});
 }
 function showAnalysis(step){
  analysisStep=step;methodStep=null;const a=step.analysis;
  $('#goldAnalysis').hidden=false;$('#goldChoice').hidden=false;
  $('#goldTerms').innerHTML='';$('#goldReview').innerHTML='';
  $('#goldAnalysis').innerHTML=`<p class="hint ${a.missing.length?'warning':''}">${esc(a.permission.state)} · 数据 ${esc(a.dataDate||'缺失')} · ${esc(a.source)}</p><p>${esc([...a.missing,...a.permission.missing,...a.permission.flaws].join('；'))}</p><div class="gold-chart"><canvas id="goldChart" aria-label="具体合约完成日K"></canvas></div><details><summary>研究与反证</summary><p>${esc(a.research)}</p><p>${esc(a.counterEvidence)}</p></details><details><summary>核对结构原始数值</summary><div class="table-wrap"><table><thead><tr><th>日期</th><th>开</th><th>高</th><th>低</th><th>收</th></tr></thead><tbody>${a.bars.slice(-20).map(b=>`<tr><td>${b.date}</td><td>${b.open}</td><td>${b.high}</td><td>${b.low}</td><td>${b.close}</td></tr>`).join('')}</tbody></table></div></details>`;
  $('#goldChoice').innerHTML=`<form id="goldChoiceForm" class="form-section"><h3>选择入场手法</h3><div class="gold-method-list">${a.candidates.map(c=>`<label class="gold-method"><input type="radio" name="method" value="${c.id}" ${c.id===a.recommended?'checked':''} required><span><b>${esc(c.name)}</b> ${c.id===a.recommended?'<span class="badge">首选建议</span>':''}<small>${esc(c.reason)}</small><small>防守：${esc(c.defense)}</small></span></label>`).join('')}</div><div class="form-grid"><label class="field">结构起点<select name="start" required>${a.bars.map(b=>`<option>${b.date}</option>`).join('')}</select></label><label class="field">结构终点<select name="end" required>${a.bars.map(b=>`<option>${b.date}</option>`).join('')}</select></label><label class="field" id="goldBranch">单边切入<select name="branch"><option value="average">穿当日分时均价线</option><option value="static">强势单边静K突破</option></select></label><label class="field">我的取舍<input name="reason" placeholder="可简记推荐或改选理由"></label></div><label class="gold-check"><input type="checkbox" name="confirmed" required>已核对同一回调、区间或单边结构；静K分支已核对强势背景及相对振幅</label><button class="primary">确认采用此手法</button></form>`;
  const form=$('#goldChoiceForm');form.querySelector('.gold-method-list').insertAdjacentHTML('afterend',intradayFields(card.direction));
  const choice=()=>({method:form.elements.method.value,start:form.elements.start.value,end:form.elements.end.value,branch:form.elements.branch.value,direction:card.direction,intraday:readIntraday(form)});
  const updateIntraday=()=>{const active=form.elements.method.value==='intraday',second=active&&form.elements.intradayConfirmation.value==='second';$('#goldIntradayParams').hidden=!active;$('#goldIntradayParams').querySelectorAll('input,select').forEach(n=>n.disabled=!active);$('#goldSecondConfirmation').hidden=!second;form.elements.intradayConfirmationRule.disabled=!second;form.elements.intradayConfirmationRule.required=second;for(const k of ['start','end'])form.elements[k].closest('label').hidden=active;form.elements.confirmed.closest('label').lastChild.textContent=active?'已核对主线、日内结构和所填参数，按独立分时方法审定，不沿用日K持有权限':'已核对同一回调、区间或单边结构；静K分支已核对强势背景及相对振幅'};
  form.restoreIntraday=q=>{for(const [key,name]of [['algorithm','intradayAlgorithm'],['confirmation','intradayConfirmation'],['confirmationRule','intradayConfirmationRule'],['tradingDay','intradayTradingDay'],['referenceAt','intradayReferenceAt'],['pivot','intradayPivot'],['stop','intradayStop']])form.elements[name].value=q[key]??'';form.elements.intradayEnvironment.checked=q.environmentConfirmed===true;form.elements.intradayStructure.checked=q.structureConfirmed===true;updateIntraday()};
  const recommend=()=>{try{sizing.suggest(deriveMethod(a,choice()))}catch{}};const redraw=()=>drawChart(a,form.elements.start.value,form.elements.end.value);const fill=()=>{const c=a.candidates.find(c=>c.id===form.elements.method.value);if(c){form.elements.start.value=c.range.start;form.elements.end.value=c.range.end;$('#goldBranch').hidden=c.id!=='trend'}updateIntraday();redraw();recommend()};
  form.elements.intradayConfirmation.onchange=()=>{updateIntraday();recommend()};$('#goldIntradayParams').addEventListener('change',recommend);
  form.querySelectorAll('[name=method]').forEach(x=>x.onchange=fill);form.elements.start.onchange=()=>{redraw();recommend()};form.elements.end.onchange=()=>{redraw();recommend()};form.elements.branch.onchange=recommend;fill();
  form.oninput=()=>{$('#goldTerms').innerHTML='';$('#goldReview').innerHTML='';methodStep=null};
  form.onsubmit=e=>{e.preventDefault();action(async()=>{const f=new FormData(form);const result=await call('choose',{analysisId:step.id,confirmed:true,reason:f.get('reason'),choice:choice()});if(!alive())return;showTerms(result);await history()},form.querySelector('button'))};
 }
 function showTerms(step){
  methodStep=step;const d=step.derived;sizing.suggest(d);if(d.method==='intraday')sizing.setPrices({entry:null,stop:d.stop,riskPercent:Math.min(sizing.values().riskPercent??.5,.5),mainCycle:'small'},{isManual:true,notify:false});const manual=sizing.values();$('#goldReview').innerHTML='';
  $('#goldStatus').textContent='手法已由本人确认，下一步审定价格与各账户手数。';
  $('#goldAnalysis').hidden=true;$('#goldChoice').hidden=false;
  const choice=$('#goldChoiceForm');if(choice){choice.elements.method.value=d.method;choice.elements.start.value=d.start;choice.elements.end.value=d.end;choice.elements.branch.value=d.branch||'average';$('#goldBranch').hidden=d.method!=='trend';if(d.intraday)choice.restoreIntraday({...d.intraday,stop:d.stop});drawChart(analysisStep.analysis,d.start,d.end)}
  $('#goldTerms').innerHTML=`<form id="goldTermsForm" class="form-section"><h3>审定入场、防守与账户</h3><p class="muted">入场与止损和上方以损定量同步；试算账户可切换，实际参与账户以此处勾选为准。</p><p><b>${esc(METHODS.find(m=>m.id===d.method)?.name)}</b> · ${esc(d.trigger)}</p><p class="muted">系统参考止损：${esc(d.stopReference)} = ${money(d.stop)}；本次止损以下方本人输入值为准。</p><p class="hint" id="goldActiveTermsHint"></p><div class="form-grid three"><label class="field">主周期<select name="mainCycle"><option value="day">日K（含分时择机）</option><option value="week">周K及以上</option><option value="small">已确认的小机会</option></select></label><label class="field">最低允许入场价<input type="number" step="any" name="entryMin" value="${manual.entry??''}" required></label><label class="field">最高允许入场价<input type="number" step="any" name="entryMax" value="${manual.entry??''}" required></label><label class="field">初始止损价<input type="number" step="any" name="stop" value="${manual.stop??''}" required></label><label class="field">首次适用交易日<input type="date" name="tradingDay" required></label><label class="field">该交易日收盘到期<input type="datetime-local" name="validUntil" required></label><label class="field wide">价格或止损调整原因<input name="adjustmentReason"></label><label class="field wide">持有与退出安排<textarea name="exitRule" required></textarea></label></div><div class="table-wrap"><table class="gold-accounts"><thead><tr><th>参与</th><th>账户 / 最新余额</th><th>风险比例%</th><th>价差测算上限</th><th>审定手数（可改小）</th><th>风险口径确认</th></tr></thead><tbody>${step.accounts.map(a=>`<tr data-account="${esc(a.id)}"><td><input type="checkbox" name="selected" aria-label="参与${esc(a.alias)}" ${a.id===card.accountId?'checked':''}></td><td>${esc(a.alias)}<br><b data-gold-account-equity>${money(a.equity)} 元</b></td><td><input type="number" name="riskPercent" min="0.001" max="1" step="0.001" value="${a.id===manual.accountId?manual.riskPercent??1:1}" aria-label="${esc(a.alias)}风险比例"></td><td><b data-gold-sizing-lots>待填写</b><small data-gold-sizing-loss></small></td><td><input type="number" name="lots" min="1" step="1" placeholder="留空按审定上限" aria-label="${esc(a.alias)}手数"></td><td><label><input type="checkbox" name="profileConfirmed">本次采用大账户口径；原更严限制保留</label></td></tr>`).join('')}</tbody></table></div><p class="muted">日K及以上上限1%，已确认小机会0.5%。按入场区间不利价格、最新余额及本机累计风险核算；费用滑点、保证金、跨品种相关风险及券商状态需另核。</p><label class="gold-check"><input type="checkbox" name="structureConfirmed" required>以上结构、防守、首次适用日和退出安排已经核对</label><button class="primary">生成审定摘要</button></form>`;
  $('#goldTerms').insertAdjacentHTML('afterbegin','<button type="button" class="secondary gold-back" id="goldBack">展开 / 收起K线分析</button>');
  $('#goldBack').onclick=()=>{$('#goldAnalysis').hidden=!$('#goldAnalysis').hidden};
  const form=$('#goldTermsForm');form.elements.tradingDay.onchange=()=>{form.elements.validUntil.value=form.elements.tradingDay.value+'T15:00'};
  if(d.method==='intraday'){
   form.elements.mainCycle.value='small';form.elements.mainCycle.disabled=true;form.elements.tradingDay.value=d.intraday.tradingDay;form.elements.tradingDay.readOnly=true;form.elements.validUntil.value=d.intraday.tradingDay+'T15:00';
   form.querySelectorAll('[name=riskPercent]').forEach(i=>{i.value=Math.min(Number(i.value)||.5,.5);i.max='.5'});
   form.querySelector('.form-grid').insertAdjacentHTML('beforeend',`<label class="field">持有安排<select name="holdingMode"><option value="intraday">日内离场（无隔夜权限）</option><option value="overnight">申请隔夜，待本人单独审定</option></select></label><label class="field">离场 / 持有截止（北京时间）<input type="datetime-local" name="holdingUntil" required></label><label class="field wide" id="goldOvernightReason" hidden>申请隔夜的依据<input name="overnightReason"></label><label class="field wide">再次试错安排<input name="reentryRule" value="未另行审定不自动复入；若获准，仍累计同一机会已损与预留，不重置预算" required></label>`);
   form.querySelector('.form-grid').insertAdjacentHTML('afterend','<label class="gold-check" id="goldOvernightCheck" hidden><input type="checkbox" name="overnightConfirmed">本人明确将本次隔夜依据和持有截止纳入最终审定，不因此取得日K持有权限</label><p class="hint">独立分时：各账户最新余额×不超过0.5%，并取原更严约束；入场价须本人填写，不沿用其他手法价格。不得随日内新低/新高向外移止损。</p>');
   form.elements.holdingMode.onchange=()=>{const overnight=form.elements.holdingMode.value==='overnight';$('#goldOvernightReason').hidden=!overnight;$('#goldOvernightCheck').hidden=!overnight;form.elements.overnightReason.required=overnight;form.elements.overnightConfirmed.required=overnight;if(!overnight){form.elements.overnightConfirmed.checked=false;form.elements.overnightReason.value=''}};
  }
  form.elements.mainCycle.onchange=()=>{form.querySelectorAll('[name=riskPercent]').forEach(i=>{i.value=form.elements.mainCycle.value==='small'?'0.5':'1';i.max=i.value});syncSizingFromTerms()};
  form.oninput=()=>{$('#goldReview').innerHTML='';syncSizingFromTerms()};updateAccountPreviews();
  form.onsubmit=e=>{e.preventDefault();action(async()=>{
   const f=new FormData(form),plan=Object.fromEntries(f);for(const k of ['entryMin','entryMax','stop'])plan[k]=Number(f.get(k));
   plan.validUntil=f.get('validUntil')+':00+08:00';plan.structureConfirmed=true;
   if(d.method==='intraday'){plan.mainCycle='small';plan.holdingUntil=f.get('holdingUntil')+':00+08:00';plan.overnightConfirmed=f.get('overnightConfirmed')==='on'}
   plan.accounts=[...form.querySelectorAll('[data-account]')].filter(tr=>tr.querySelector('[name=selected]').checked).map(tr=>({id:tr.dataset.account,riskPercent:Number(tr.querySelector('[name=riskPercent]').value),lots:tr.querySelector('[name=lots]').value===''?null:Number(tr.querySelector('[name=lots]').value),profileConfirmed:tr.querySelector('[name=profileConfirmed]').checked}));
   const r=await call('review',{methodId:step.id,plan});if(alive()){showReview(r);await history()}
  },form.querySelector('button'))};
 }
 function showReview(r){
  $('#goldStatus').textContent=r.errors.length?'审定存在待补项，尚未批准。':'审定摘要已生成，尚未最终拍板。';
  $('#goldReview').innerHTML=`<section class="form-section"><h3>待你最终拍板</h3><p>${money(r.input.entryMin)} ～ ${money(r.input.entryMax)} 入场 · ${money(r.input.stop)} 止损 · ${esc(r.input.tradingDay)} 适用</p><div class="table-wrap"><table><thead><tr><th>账户</th><th>最新余额</th><th>本轮余额度</th><th>核算上限</th><th>审定手数</th><th>价差风险</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${esc(x.alias)}</td><td>${money(x.equity)}</td><td>${money(x.risk.remainingBudget)}</td><td>${money(x.maximumLots)}</td><td>${money(x.risk.lots)}</td><td>${money(x.risk.plannedLoss)}</td></tr>`).join('')}</tbody></table></div><p>${esc(r.input.exitRule)}</p>${r.errors.length?`<p class="hint warning">${r.errors.map(esc).join('；')}</p>`:'<p class="hint">等待触发，不等于已成交；确认仅保存计划，实际下单由团队执行。</p>'}<label class="gold-check"><input type="checkbox" id="goldFinalCheck">本人已核对方案及各账户，决定采用此版本</label><button type="button" class="primary" id="goldApprove" ${r.errors.length?'disabled':''}>本人拍板 · 确认这份方案</button></section>`;
  if(r.input.holdingMode)$('#goldFinalCheck').closest('label').insertAdjacentHTML('beforebegin',`<p class="hint">独立分时，风险上限0.5%；${r.input.holdingMode==='overnight'?'本次申请隔夜，须在最终拍板中单独审定':'仅限日内，未获隔夜权限'}；持有截止 ${esc(r.input.holdingUntil)}。${esc(r.input.reentryRule)}${r.input.holdingMode==='overnight'?'；隔夜依据：'+esc(r.input.overnightReason):''}</p>`);
  $('#goldApprove').onclick=e=>{if(!$('#goldFinalCheck').checked)return toast('请先确认最终审定',true);action(async()=>{await call('approve',{reviewId:r.id,confirmationHash:r.confirmationHash,confirmed:true});if(alive()){toast('已记录拍板；未发送任何交易指令');await onApproved()}},e.currentTarget)};
 }
 $('#analyzeGold').onclick=e=>action(async()=>{const result=await call('analyze');if(alive()){showAnalysis(result);$('#goldStatus').textContent='分析已留档，尚未确认手法或批准交易。';await history()}},e.currentTarget);
 try{const list=await history();if(!alive())return;const latest=list[0];if(latest&&latest.stage!=='approved'){
  const a=list.find(x=>x.stage==='analysis');if(a?.analysis.ruleVersion!==GOLD_RULE&&a){$('#goldStatus').textContent='旧版分析和审定已保留；新增独立分时第五法，请点击“分析五种手法”生成新版，不能沿用旧确认。';return}if(a)showAnalysis(a);
  const m=list.find(x=>x.stage==='method');if(m&&(!a||m.analysisId===a.id)){
   showTerms(m);
   if(latest.stage==='review'&&latest.methodId===m.id){
    const f=$('#goldTermsForm');
    for(const [key,value] of Object.entries(latest.input))if(f.elements[key]&&typeof value!=='object'){
     if(f.elements[key].type==='checkbox')f.elements[key].checked=value===true;
     else f.elements[key].value=['validUntil','holdingUntil'].includes(key)?String(value).slice(0,16):value;
    }
    for(const tr of f.querySelectorAll('[data-account]')){
     const saved=latest.input.accounts.find(x=>x.id===tr.dataset.account);
     tr.querySelector('[name=selected]').checked=!!saved;
     if(saved){tr.querySelector('[name=riskPercent]').value=saved.riskPercent;tr.querySelector('[name=lots]').value=saved.lots??'';tr.querySelector('[name=profileConfirmed]').checked=saved.profileConfirmed===true}
    }
    if(f.elements.holdingMode)f.elements.holdingMode.onchange();if(latest.input.overnightConfirmed&&f.elements.overnightConfirmed)f.elements.overnightConfirmed.checked=true;syncSizingFromTerms();showReview(latest);
   }
  }
  $('#goldStatus').textContent='已恢复上次记录；行情或余额变化后需重新审定。';
 }else if(latest)$('#goldStatus').textContent='上一版已拍板；重新分析不会改写上一版。'}catch(e){if(alive())$('#goldStatus').textContent=e.message}
}
